WITH kept_keys AS (SELECT id, city FROM stores INTERSECT SELECT id, city FROM stores WHERE region = 'North'), reconciled AS (SELECT s.* FROM stores s INNER JOIN kept_keys k ON s.id = k.id AND s.city = k.city) SELECT id, store_name, city, region, opened_date, CASE WHEN city RLIKE '^(Singapore|London)$' THEN 'EXTENDED' WHEN city RLIKE '^(Bangkok|Chiang Mai)$' THEN 'GROUP_B' ELSE 'PRIORITY' END AS city_zone FROM reconciled ORDER BY city_zone DESC NULLS LAST;
